cd /app && python3 - <<'EOF'
import pickle,json
frames,unk=pickle.load(open('cmds/pass4.pkl','rb'))
D=dict(frames)
lines=json.load(open('cmds/lines.json'))   # (idx, frame, typedtext)
def clean(s):
    if '\x00' in s: s=s.split('\x00')[0]
    return s.replace('\x01','').replace('\x02','').rstrip()
res=[]
bad=[]
for i,(idx,fr,t) in enumerate(lines):
    if i+1<len(lines):
        nf=lines[i+1][1]
    else:
        nf=None
    echo=None
    if nf is not None:
        # search from nf forward for a frame present in D
        for f in range(nf, nf+15):
            if f in D:
                out=list(reversed(D[f]))  # top->bottom
                if len(out)>=2:
                    e=clean(out[-2])
                    if e.startswith('>'): echo=e[1:].rstrip()
                break
    res.append((i,fr,t,echo))
    if echo is None or echo!=t: bad.append((i,fr,t,echo))
print('groups',len(res),'mismatch',len(bad))
for b in bad: print(b)
json.dump(res,open('cmds/echo.json','w'))
EOF
